// Bakes prompts/*.md into src/lib/ai/prompts.generated.ts so no deployed function reads the disk.
// Run `npm run prompts` after editing a prompt; `npm run test` fails if the generated file is stale.
import { readdirSync, readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";

const root = new URL("..", import.meta.url).pathname;
const names = readdirSync(join(root, "prompts")).filter((f) => f.endsWith(".md")).map((f) => f.slice(0, -3)).sort();
const body = names.map((n) => `  ${JSON.stringify(n)}: ${JSON.stringify(readFileSync(join(root, "prompts", `${n}.md`), "utf8"))},`).join("\n");
writeFileSync(
  join(root, "src/lib/ai/prompts.generated.ts"),
  `// Generated by scripts/gen-prompts.mjs from prompts/*.md. Do not edit.\nexport const PROMPTS = {\n${body}\n} as const;\n`,
);
